head.script:
/* 최상단(opener, parent 포함) 기준 함수 */
scwin.isMain = function() {
    return true;
};

/* 검색조건 */
scwin.param;

/**
 *  물건 상세검색 MAIN 프레임
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.12.28.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function(e) {

    const jsonInput = JSON.parse($w.local.getItem('dtlSrchParam')) || '';
    $w.local.removeItem('dtlSrchParam');

    let urlPath = "";
    let srchInfo = "";
    let prevInfo = "";
    let csNo = "";
    let cortOfcCd = "";
    let dspslGdsSeq = "";
    let pgmId = "";
    let dtlObj = '';

    if (!scutilo.isEmpty(jsonInput)) {
        srchInfo = jsonInput.srchInfo
        prevInfo = jsonInput.prevInfo
        csNo = jsonInput.scNo
        cortOfcCd = jsonInput.cortOfcCd
        dspslGdsSeq = jsonInput.dspslGdsSeq
        pgmId = jsonInput.pgmId
    }
    switch (pgmId) {
        /* 나의검색 화면에서 물건 선택시 물건 상세화면 이동 */
        case 'PGJ15BP05':case 'PGJ111M01': case'PGJ152P02': case 'PGJ192M01': case 'PGJ193M01' : 
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { csNo,cortOfcCd,dspslGdsSeq,pgmId,srchInfo,prevInfo}
                }
            };
            document.title = '법원경매정보제공 - 물건상세내역'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15BM01.xml',dtlObj);
            break;
        /* 물건상세화면(동산) */
        case 'PGJ152F07' :
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { csNo,cortOfcCd,dspslGdsSeq,pgmId,srchInfo,prevInfo}
                }
            };
            document.title = '법원경매정보제공 - 물건상세내역'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15BM04.xml',dtlObj);
            break
        /* 사이트맵에서 동산,부동산 화면 이동분류 */
        case 'PGJ185M01' :
            if (srchInfo.pgmNm === 'gdsDtl') {
                urlPath = '/pgj/ui/pgj100/PGJ151F01.xml'
                document.title = '법원경매정보제공 - 물건상세검색'
            } else if (srchInfo.pgmNm === 'dxdy') {
                urlPath = '/pgj/ui/pgj100/PGJ153F01.xml'
                document.title = '법원경매정보제공 - 기일별검색'
            }
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { tapDvsCd : srchInfo.tapDvsCd }
                }
            };
            $p.main().wfm_mainFrame.setSrc(urlPath,dtlObj);
            break;
        /* (공통) 사건상세화면 */
        case 'PGJ15AF01' :
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { sideDvsCd : srchInfo.sideDvsCd,menuNm: srchInfo.menuNm, userCsNo: srchInfo.userCsNo,csNo,cortOfcCd,srchInfo,prevInfo}
                }
            };
            document.title = '법원경매정보제공 - 사건상세내역'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15AF01.xml',dtlObj);
            break
        /* 메인 용도별(부동산) 검색 */
        case 'mainUsg' :
            srchInfo.pgmId = "PGJ151M01";
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { pgmId,srchInfo}
                }
            };
            document.title = '법원경매정보제공 - 물건상세검색(부동산)'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ151M01.xml',dtlObj);
            break
        /* 메인 빠른검색 동산 */
        case 'mvprpSrch' :
            srchInfo.pgmId = "PGJ151M02";
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { pgmId,srchInfo}
                }
            };
            document.title = '법원경매정보제공 - 물건상세검색(동산)'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ151M02.xml',dtlObj);
            break
        /* 메인 용도별 차량 검색 */
        case 'mainUsgCar' :
            srchInfo.pgmId = "PGJ154M02";
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : {
                    cortAuctnSrchCondCd : srchInfo.cortAuctnSrchCondCd,
                    lclDspslGdsLstUsgCd : srchInfo.lclDspslGdsLstUsgCd,
                    mclDspslGdsLstUsgCd : srchInfo.mclDspslGdsLstUsgCd,
                    sclDspslGdsLstUsgCd : srchInfo.sclDspslGdsLstUsgCd,
                    csNo : "",
                    cortOfcCd : "",
                    srchInfo,
                    prevInfo}
                }
            };
            document.title = '법원경매정보제공 - 자동차ㆍ중기 검색'
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ154M02.xml',dtlObj);
            break
        default :
            dtlObj = {
                "dataObject": { "type" : "json",
                "name" : "param",
                "data" : { prevInfo,srchInfo}
                }
            };
            document.title = '법원경매정보제공 - 물건상세검색' 
            $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ151F01.xml',dtlObj);
    }
};

scwin.onpageunload = function() {

};
